@push('scripts')@unless(app()->environment(['local','testing']) && config('travel.checkout.demo_payment_enabled'))<script src="https://js.paystack.co/v2/inline.js"></script>@endunless<script>
(()=>{const csrf=document.querySelector('meta[name="csrf-token"]').content;const init=@json(\Illuminate\Support\Facades\URL::signedRoute('checkout.hold.pay.initialize',['order'=>$order],absolute:false));const verify=@json(\Illuminate\Support\Facades\URL::signedRoute('checkout.hold.pay.verify',['order'=>$order],absolute:false));const btn=document.querySelector('[data-pay]');const error=document.querySelector('[data-payment-error]');const post=async(url,data={})=>{const r=await fetch(url,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:new URLSearchParams(data)});const b=await r.json();if(!r.ok)throw Error(b.message||'Payment could not be started.');return b};btn.addEventListener('click',async()=>{btn.disabled=true;try{const b=await post(init);if(b.public_key==='demo'){const v=await post(verify,{reference:b.reference});location.href=v.redirect;return}const p=new PaystackPop();p.newTransaction({key:b.public_key,email:b.email,amount:b.amount_minor,currency:b.currency,reference:b.reference,onSuccess:async t=>{try{const v=await post(verify,{reference:t.reference||b.reference});location.href=v.redirect}catch(e){error.textContent=e.message;error.classList.remove('d-none');btn.disabled=false}},onCancel:()=>btn.disabled=false})}catch(e){error.textContent=e.message;error.classList.remove('d-none');btn.disabled=false}})})();</script>@endpush
